using AutoMapper;
using CarWorkshop.Application.CarWorkshop.Commands.EditCarWorkshopCommand;
using CarWorkshop.Application.CarWorkshop.Commands.Queries;
using CarWorkshop.Application.Commands.CreateCarWorkshopCommand;
using MediatR;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace CarWorkshop.MVC.Controllers;

public class CarWorkshopController : Controller
{
    private readonly IMediator _mediator;
    private readonly IMapper _mapper;
    public CarWorkshopController(IMediator mediator,IMapper mapper)
    {
        _mediator = mediator;
        _mapper = mapper;
    }

    public async Task<IActionResult> Index()
    {
        var carWorkshops =await  _mediator.Send(new GetAllCarWorkshopQuery());
        return View(carWorkshops);
    }

    [HttpGet]
    [Route("CarWorkshop/{encodedName}/Details")]
    public async Task<IActionResult> Details(string encodedName)
    {
        var dto =await _mediator.Send(new GetCarWorkshopByEncodedNameQuery(encodedName));
        return View(dto);
    }


    [HttpPost]
    [ValidateAntiForgeryToken]
    [Route("CarWorkshop/{encodedName}/Edit")]
    public async Task<IActionResult> Edit(string encodedName,EditCarWorkshopCommand command)
    {

        if (!ModelState.IsValid)
        {
            return View(command);
        }
        await _mediator.Send(command);
        return RedirectToAction(nameof(Index)); 
    }

    [HttpGet]
    [Route("CarWorkshop/{encodedName}/Edit")]
    public async Task<IActionResult> Edit(string encodedName)
    {
        var dto = await _mediator.Send(new GetCarWorkshopByEncodedNameQuery(encodedName));
        if(dto.IsEdible == false)
        {
            return RedirectToAction("NoAccess", "Home");
        }
        EditCarWorkshopCommand model = _mapper.Map<EditCarWorkshopCommand>(dto);
        return View(model);
    }


    [Authorize(Roles = "Owner")]
    public IActionResult Create()
    {

        return View();
    }

    [HttpPost]
    [Authorize(Roles = "Owner")]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(CreateCarWorkshopCommand command)
    {
        if (!ModelState.IsValid)
        {
            return View(command);
        }
        await _mediator.Send(command);
        return RedirectToAction(nameof(Index)); 
    }
}

using AutoMapper;
using CarWorkshop.Application.CarWorkshop.Commands.EditCarWorkshopCommand;
using CarWorkshop.Application.CarWorkshop.Commands.Queries;
using CarWorkshop.Application.Commands.CreateCarWorkshopCommand;
using MediatR;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace CarWorkshop.MVC.Controllers;

public class CarWorkshopController : Controller
{
    private readonly IMediator _mediator;
    private readonly IMapper _mapper;
    public CarWorkshopController(IMediator mediator,IMapper mapper)
    {
        _mediator = mediator;
        _mapper = mapper;
    }

    public async Task<IActionResult> Index()
    {
        var carWorkshops =await  _mediator.Send(new GetAllCarWorkshopQuery());
        return View(carWorkshops);
    }

    [HttpGet]
    [Route("CarWorkshop/{encodedName}/Details")]
    public async Task<IActionResult> Details(string encodedName)
    {
        var dto =await _mediator.Send(new GetCarWorkshopByEncodedNameQuery(encodedName));
        return View(dto);
    }


    [HttpPost]
    [ValidateAntiForgeryToken]
    [Route("CarWorkshop/{encodedName}/Edit")]
    public async Task<IActionResult> Edit(string encodedName,EditCarWorkshopCommand command)
    {

        if (!ModelState.IsValid)
        {
            return View(command);
        }
        await _mediator.Send(command);
        return RedirectToAction(nameof(Index)); 
    }

    [HttpGet]
    [Route("CarWorkshop/{encodedName}/Edit")]
    public async Task<IActionResult> Edit(string encodedName)
    {
        var dto = await _mediator.Send(new GetCarWorkshopByEncodedNameQuery(encodedName));
        if(dto.IsEdible == false)
        {
            return RedirectToAction("NoAccess", "Home");
        }
        EditCarWorkshopCommand model = _mapper.Map<EditCarWorkshopCommand>(dto);
        return View(model);
    }


    [Authorize(Roles = "Owner")]
    public IActionResult Create()
    {

        return View();
    }

    [HttpPost]
    [Authorize(Roles = "Owner")]
    [ValidateAntiForgeryToken]
    public async Task<IActionResult> Create(CreateCarWorkshopCommand command)
    {
        if (!ModelState.IsValid)
        {
            return View(command);
        }

        try
        {
            await _mediator.Send(command);
        }
        catch (ValidationException ex)
        {
            foreach (var error in ex.Errors)
            {
                ModelState.AddModelError(error.PropertyName, error.ErrorMessage);
            }
            return View(command);
        }

        return RedirectToAction(nameof(Index)); 
    }
}

using AutoMapper;
using CarWorkshop.Application.ApplicationUser;
using CarWorkshop.Application.CarWorkshop;
using CarWorkshop.Application.CarWorkshop.Commands.EditCarWorkshopCommand;
using CarWorkshop.Application.Commands.CreateCarWorkshopCommand;
using CarWorkshop.Application.Mappings;
using FluentValidation;
using FluentValidation.AspNetCore;
using MediatR;
using Microsoft.Extensions.DependencyInjection;

namespace CarWorkshop.Application.Extensions;

public static class ServiceCollectionExtension
{
    public static void AddApplication(this IServiceCollection services)
    {
        services.AddMediatR(typeof(CreateCarWorkshopCommand));
        services.AddAutoMapper(typeof(CarWorkshopMappingProfile));
        services.AddValidatorsFromAssemblyContaining<CreateCarWorkshopCommandValidator>();
        services.AddValidatorsFromAssemblyContaining<EditCarWorkshopValidator>();
        services.AddFluentValidationAutoValidation();
        services.AddFluentValidationClientsideAdapters();
        services.AddScoped<IUserContext, UserContext>();
        services.AddScoped(provider => new MapperConfiguration(cfg =>
        {
            var scope = provider.CreateScope();
            var userContext = scope.ServiceProvider.GetRequiredService<IUserContext>();
            cfg.AddProfile(new CarWorkshopMappingProfile(userContext));
        }).CreateMapper());
    }
}

using AutoMapper;
using CarWorkshop.Application.ApplicationUser;
using CarWorkshop.Application.Behaviors;
using CarWorkshop.Application.CarWorkshop;
using CarWorkshop.Application.CarWorkshop.Commands.EditCarWorkshopCommand;
using CarWorkshop.Application.Commands.CreateCarWorkshopCommand;
using CarWorkshop.Application.Mappings;
using FluentValidation;
using FluentValidation.AspNetCore;
using MediatR;
using Microsoft.Extensions.DependencyInjection;

namespace CarWorkshop.Application.Extensions;

public static class ServiceCollectionExtension
{
    public static void AddApplication(this IServiceCollection services)
    {
        services.AddMediatR(typeof(CreateCarWorkshopCommand));
        services.AddTransient(typeof(IPipelineBehavior<,>), typeof(ValidationBehavior<,>));
        services.AddAutoMapper(typeof(CarWorkshopMappingProfile));
        services.AddValidatorsFromAssemblyContaining<CreateCarWorkshopCommandValidator>();
        services.AddValidatorsFromAssemblyContaining<EditCarWorkshopValidator>();
        services.AddFluentValidationClientsideAdapters();
        services.AddScoped<IUserContext, UserContext>();
        services.AddScoped(provider => new MapperConfiguration(cfg =>
        {
            var scope = provider.CreateScope();
            var userContext = scope.ServiceProvider.GetRequiredService<IUserContext>();
            cfg.AddProfile(new CarWorkshopMappingProfile(userContext));
        }).CreateMapper());
    }
}
